module native_owner_atomic_probe;
import core.atomic : atomicLoad, atomicStore, cas, MemoryOrder;
@safe:
private shared ulong ownerCounter;
ulong nextOwner() nothrow @nogc
{
    ulong seen = atomicLoad!(MemoryOrder.raw)(ownerCounter);
    while (seen != ulong.max)
    {
        if (cas!(MemoryOrder.raw, MemoryOrder.raw)(&ownerCounter, seen, seen + 1))
            return seen + 1;
        seen = atomicLoad!(MemoryOrder.raw)(ownerCounter);
    }
    return 0;
}
extern(C) int main() nothrow @nogc
{
    assert(nextOwner() == 1);
    assert(nextOwner() == 2);
    atomicStore!(MemoryOrder.raw)(ownerCounter, ulong.max - 1);
    assert(nextOwner() == ulong.max);
    assert(nextOwner() == 0);
    assert(nextOwner() == 0);
    return 0;
}
